using System;using System.IO;using System.IO.Compression;using UnityEngine;
public sealed class DensePoseData {
 public Vector3[] vertices;public byte[] counts,bones;public float[] weights;public int[] offsets,feet;public Matrix4x4[] binds;
 public static DensePoseData Read(byte[] packed){using(var src=new MemoryStream(packed))using(var z=new DeflateStream(src,CompressionMode.Decompress))using(var buf=new MemoryStream()){z.CopyTo(buf);using(var r=new BinaryReader(new MemoryStream(buf.ToArray()))){if(r.ReadUInt32()!=0x3150444c)throw new InvalidDataException("Dense proof magic");int v=r.ReadInt32(),n=r.ReadInt32(),b=r.ReadInt32(),f=r.ReadInt32();var d=new DensePoseData{vertices=new Vector3[v],counts=new byte[v],bones=new byte[n],weights=new float[n],offsets=new int[v+1],binds=new Matrix4x4[b],feet=new int[f]};for(int k=0;k<v;k++)d.vertices[k]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());d.counts=r.ReadBytes(v);d.bones=r.ReadBytes(n);for(int k=0;k<n;k++)d.weights[k]=r.ReadSingle();for(int k=0;k<b;k++){var m=new Matrix4x4();for(int q=0;q<16;q++)m[q]=r.ReadSingle();d.binds[k]=m;}for(int k=0;k<f;k++)d.feet[k]=r.ReadInt32();for(int k=0;k<v;k++)d.offsets[k+1]=d.offsets[k]+d.counts[k];return d;}}}
 public Matrix4x4[] Matrices(Transform[] rig){var result=new Matrix4x4[binds.Length];for(int k=0;k<result.Length;k++)result[k]=rig[k].localToWorldMatrix*binds[k];return result;}
 public Vector3 Point(int index,Matrix4x4[] matrices){var p=Vector3.zero;for(int k=offsets[index];k<offsets[index+1];k++)p+=matrices[bones[k]].MultiplyPoint3x4(vertices[index])*weights[k];return p;}
 public float Minimum(int[] indices,Matrix4x4[] matrices,out int at){float min=float.PositiveInfinity;at=-1;foreach(int k in indices){float y=Point(k,matrices).y;if(y<min){min=y;at=k;}}return min;}
 public CandidateFootGrounding.Point Support(int id){var w=new CandidateFootGrounding.Influence[counts[id]];for(int k=0;k<w.Length;k++){int i=offsets[id]+k;w[k]=new CandidateFootGrounding.Influence{bone=bones[i],weight=weights[i],bindPoint=binds[bones[i]].MultiplyPoint3x4(vertices[id])};}return new CandidateFootGrounding.Point{influences=w};}
}
